using ClearTone;
void Assert(bool condition,string reason){if(!condition)throw new InvalidOperationException(reason);}
Assert(ReadingDisplay.Resolve(-1,false)==ReadingDisplay.Off,"Existing disabled annotation stays off");
Assert(ReadingDisplay.Resolve(-1,true)==ReadingDisplay.Romaji,"Existing enabled romanization stays enabled on upgrade");
Assert(ReadingDisplay.Resolve(ReadingDisplay.Hiragana,true)==ReadingDisplay.Hiragana,"Saved tri-state takes priority over legacy flag");
int mode=ReadingDisplay.Off;mode=ReadingDisplay.Next(mode);Assert(mode==ReadingDisplay.Hiragana,"First click shows hiragana");mode=ReadingDisplay.Next(mode);Assert(mode==ReadingDisplay.Romaji,"Second click shows romaji");mode=ReadingDisplay.Next(mode);Assert(mode==ReadingDisplay.Off,"Third click disables annotations");
Assert(ReadingDisplay.HiraganaOf("キミ・カナ") == "きみ・かな","Corrections are normalized without altering punctuation");
Assert(ReadingDisplay.Ruby(new("空","ソラ"))=="そら","Kanji receives hiragana");
Assert(ReadingDisplay.Ruby(new("ひらがな","ひらがな"))=="","Matching kana does not repeat above itself");
var mixed=new List<ReadingToken>{new("Hello"),new("世界","せかい","sekai")};
Assert(ReadingDisplay.Romanization(new(0,"Hello世界"),mixed,false)=="Hello sekai","Mixed scripts retain unannotated words");
Assert(ReadingDisplay.Romanization(new(0,"Hello世界",Romanization:"source roman"),mixed,false)=="source roman","Source romanization takes priority");
Assert(ReadingDisplay.Romanization(new(0,"Hello世界",Romanization:"source roman"),mixed,true)=="Hello sekai","Corrections override source romanization");
Assert(ReadingDisplay.Romanization(new(0,"Instrumental"),[new("Instrumental")],false)=="","Unannotated text is not duplicated");
var lines=new List<Lyric>{new(2,"君の空"),new(5,"夢を見る"),new(5,"重なる声"),new(8,"明日")};
Assert(PracticeTiming.Current(lines,.5,0)==0,"Lead-in follows the first line");
Assert(PracticeTiming.Current(lines,.5,5.49)==0,"Positive offset delays the transition");
Assert(PracticeTiming.Current(lines,.5,5.5)==2,"Follow advances at the exact boundary and honors duplicate timestamps");
Assert(PracticeTiming.Current(lines,0,8)==3,"Continuous follow reaches the final line");
Assert(PracticeTiming.Current([],0,100)==-1,"Empty lyrics have no selected line");
Console.WriteLine("PASS: annotation migration/cycle, hiragana normalization, mixed-script romaji and continuous timeline following");
var karaoke=KaraokeTimeline.Build(new(10,"君 の空"),15,[new("君","きみ"),new(" の空","のそら")],[new(10,5,"君の空",[new(10,1,"君"),new(12,1,"の"),new(14,1,"空")])]);
Assert(karaoke.Exact&&karaoke.Characters==4,"YRC matches independently of LRC whitespace");
Assert(karaoke.Progress(9)==0&&karaoke.Progress(10.5)==.5,"YRC uses absolute word timing");
Assert(karaoke.Progress(11.5)==1&&karaoke.Progress(15)==4,"YRC preserves instrumental gaps and completes the last word");
Assert(karaoke.Fraction(2,2,14.5)==.75,"Token highlight maps to the shared character cursor");
Assert(karaoke.Progress(10.2)<karaoke.Progress(14.2),"Seeking backwards immediately rewinds karaoke");
var estimate=KaraokeTimeline.Build(new(1,"空へ"),4,[new("空","そら"),new("へ","へ")],[]);
Assert(!estimate.Exact&&Math.Abs(estimate.Progress(2)-.5)<.001&&estimate.Progress(4)==2,"LRC estimate weights kanji by reading mora");
var mismatch=KaraokeTimeline.Build(new(10,"違う歌詞"),12,[],[new(10,2,"君の空",[new(10,2,"君の空")])]);Assert(!mismatch.Exact,"Different lyric editions never borrow exact timing");
var duplicate=KaraokeTimeline.Build(new(30,"君"),32,[],[new(10,1,"君",[new(10,1,"君")]),new(30,1,"君",[new(30,1,"君")])]);Assert(duplicate.Exact&&duplicate.Progress(30.5)==.5,"Repeated lyrics choose the nearest timestamp");
var invalid=KaraokeTimeline.Build(new(0,"声"),2,[],[new(0,2,"声",[new(0,-1,"声")])]);Assert(!invalid.Exact,"Invalid source durations fall back safely");
var punctuation=KaraokeTimeline.Build(new(0,"声！"),1,[],[new(0,1,"声！",[new(0,1,"声"),new(1,0,"！")])]);Assert(punctuation.Exact&&punctuation.Progress(.9)<1&&punctuation.Progress(1)==2,"Source zero-duration punctuation completes at its real boundary");
var overlapping=KaraokeTimeline.Build(new(0,"声空"),2,[],[new(0,2,"声空",[new(0,2,"声"),new(1,1,"空")])]);Assert(overlapping.Exact&&overlapping.Progress(1.5)==1.5,"An overlapping source word begins at its own timestamp");
var unicode=KaraokeTimeline.Build(new(0,"あ👩‍🎤e\u0301"),3,[],[]);Assert(unicode.Characters==3&&unicode.Progress(3)==3,"Emoji and combining accents stay intact");
Assert(estimate.Progress(2.5-.5)==estimate.Progress(2),"Lyric offset is applied on the media timeline before sampling");
Console.WriteLine("PASS: exact YRC timing, silence gaps, backward seek, mora estimates, mismatches, repeated lines and grapheme safety");
